import{_ as e,o,c as a,a2 as r}from"./chunks/framework.mRCPFc5l.js";const i="/assets/timeline-and-timing.C612mNf2.png",l="/assets/timing-editor.BvbWkrwz.png",m=JSON.parse('{"title":"审校字幕","description":"","frontmatter":{},"headers":[],"relativePath":"03-reviewing-subtitles.md","filePath":"zh-CN/03-reviewing-subtitles.md"}'),d={name:"03-reviewing-subtitles.md"};function n(s,t,c,h,p,g){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="审校字幕" tabindex="-1">审校字幕 <a class="header-anchor" href="#审校字幕" aria-label="Permalink to &quot;审校字幕&quot;">​</a></h1><p>结合表格、视频和时间轴，逐条核对并修改字幕。</p><h2 id="你可以在本页完成什么" tabindex="-1">你可以在本页完成什么 <a class="header-anchor" href="#你可以在本页完成什么" aria-label="Permalink to &quot;你可以在本页完成什么&quot;">​</a></h2><ul><li>选择和编辑字幕单元格。</li><li>让表格焦点、视频位置和时间轴保持同步。</li><li>调整字幕开始和结束时间。</li><li>在同集或跨集字幕之间导航。</li><li>撤销、重做或检查当前修改。</li></ul><h2 id="浏览和选择字幕" tabindex="-1">浏览和选择字幕 <a class="header-anchor" href="#浏览和选择字幕" aria-label="Permalink to &quot;浏览和选择字幕&quot;">​</a></h2><p>点击表格单元格会聚焦对应字幕行。左侧行标记可建立明确的行选择；拖动单元格可建立矩形范围；按住 <code>Ctrl</code>（macOS：<code>Command</code>） 可以追加范围，按住 <code>Shift</code> 可以扩展当前选择。</p><p>表格左上角的选择框用于选择或取消选择所有<strong>当前可见行</strong>。筛选开启时，隐藏行不会被行操作选中。</p><p>进入多选状态时，视频会暂停，避免播放跟踪改变正在批量处理的目标。重新单击普通单元格会回到单一焦点行。</p><h2 id="编辑原文与译文" tabindex="-1">编辑原文与译文 <a class="header-anchor" href="#编辑原文与译文" aria-label="Permalink to &quot;编辑原文与译文&quot;">​</a></h2><p>双击可编辑单元格，或直接键入内容开始编辑。按 <code>Enter</code> 提交后焦点保持在对应行，便于继续使用键盘导航。</p><p>常见字段：</p><table tabindex="0"><thead><tr><th>字段</th><th>用途</th></tr></thead><tbody><tr><td><code>episode</code></td><td>字幕所属集数</td></tr><tr><td><code>start</code> / <code>end</code></td><td>毫秒形式的权威时间</td></tr><tr><td><code>text</code></td><td>原文字幕</td></tr><tr><td><code>translation</code></td><td>译文字幕，主要审校字段</td></tr><tr><td><code>start_h</code> / <code>end_h</code></td><td>人类可读时间</td></tr><tr><td><code>duration_h</code>、<code>chars</code>、<code>cps</code></td><td>自动计算的时长、字符数和阅读速度</td></tr></tbody></table><p>自动计算字段是只读的；编辑译文或时间后会重新计算。隐藏的元数据列可在 <strong>设置 → 显示隐藏列</strong> 中显示，但修改前应确认自己理解其用途。</p><h2 id="复制、粘贴和填充内容" tabindex="-1">复制、粘贴和填充内容 <a class="header-anchor" href="#复制、粘贴和填充内容" aria-label="Permalink to &quot;复制、粘贴和填充内容&quot;">​</a></h2><p>选中单元格后可使用 <code>Ctrl+C</code>（macOS：<code>Command+C</code>）、<code>Ctrl+X</code>（macOS：<code>Command+X</code>）、<code>Ctrl+V</code>（macOS：<code>Command+V</code>） 或右键菜单。应用支持：</p><ul><li>包含多行文本的单元格。</li><li>从电子表格复制的 HTML 表格。</li><li>将矩形数据粘贴到当前可见行。</li><li>使用选区右下角的填充柄向下复制可编辑内容。</li></ul><p>明确的行选择不允许直接剪切或清空，防止未复制的整行内容被删除。派生字段也不能清空或粘贴覆盖。</p><h2 id="播放和切换视频" tabindex="-1">播放和切换视频 <a class="header-anchor" href="#播放和切换视频" aria-label="Permalink to &quot;播放和切换视频&quot;">​</a></h2><p>视频区域提供：</p><ul><li><strong>上一个</strong>、<strong>播放/暂停</strong>、<strong>下一个</strong>。</li><li>当前视频选择器。</li><li>播放时间和进度。</li><li>播放速度。</li><li>时间轴缩放。</li></ul><p>点击视频画面或按 <code>Space</code> 可切换播放状态。使用上下方向键跳转字幕不会擅自改变当前播放/暂停状态。</p><p>当焦点移动到另一集字幕时，应用会切换到匹配视频；视频加载完成后再恢复目标行和播放位置。没有匹配视频时会显示“视频缺失”，字幕仍可继续编辑。</p><h2 id="使用时间轴定位字幕" tabindex="-1">使用时间轴定位字幕 <a class="header-anchor" href="#使用时间轴定位字幕" aria-label="Permalink to &quot;使用时间轴定位字幕&quot;">​</a></h2><p><img src="'+i+'" alt="视频时间轴上的字幕块、播放头和时间调整工具"></p><ul><li>点击时间轴空白处：移动播放头，并聚焦该时间点的字幕；间隙中会选择之前最近的一条。</li><li>点击字幕块：跳转到对应字幕并让表格重新获得键盘焦点。</li><li>鼠标滚轮：调整时间轴缩放。</li><li>手动横向滚动或拖动：暂时保留当前视野，避免播放头立即把时间轴拉回。</li></ul><p>播放时，当前字幕、表格焦点、行高亮和活动字幕块会同步。搜索或筛选正在使用时，播放跟踪不会抢回当前编辑焦点。</p><h2 id="调整字幕开始和结束时间" tabindex="-1">调整字幕开始和结束时间 <a class="header-anchor" href="#调整字幕开始和结束时间" aria-label="Permalink to &quot;调整字幕开始和结束时间&quot;">​</a></h2><ol><li>先聚焦一行字幕。</li><li>点击视频工具区的 <strong>调整时间</strong>。</li><li>输入开始和结束时间，或点击 <strong>使用播放头</strong>。</li><li>检查当前播放头和警告。</li><li>点击 <strong>应用时间</strong>。</li></ol><p><img src="'+l+'" alt="字幕时间编辑器，包含开始、结束和使用播放头按钮"></p><p>时间格式使用 <code>HH:MM:SS.mmm</code>，也接受逗号毫秒分隔。结束时间必须晚于开始时间。</p><p>如果新时间与其他字幕重叠，或会改变该行在当前集的时间顺序，应用会先显示警告。确认无误后可以选择 <strong>仍然应用</strong>。</p><p>拖动时间轴字幕块只更新编辑器草稿，点击应用前不会直接写入工作区。</p><h2 id="在字幕和集数之间导航" tabindex="-1">在字幕和集数之间导航 <a class="header-anchor" href="#在字幕和集数之间导航" aria-label="Permalink to &quot;在字幕和集数之间导航&quot;">​</a></h2><ul><li><code>Arrow Up</code> / <code>Arrow Down</code>：上一条或下一条字幕。</li><li>视频区 <strong>上一个</strong> / <strong>下一个</strong>：在边界处切换到相邻集，并聚焦第一条或最后一条字幕。</li><li>顶部集数选择器：直接切换目标集。</li><li>质量摘要、拼写检查和查找结果也可以跳转到目标行。</li></ul><p>重叠时间范围内，手动聚焦的字幕在自身时间范围中保持优先；普通连续播放则优先显示开始更晚的字幕。</p><h2 id="撤销和重做修改" tabindex="-1">撤销和重做修改 <a class="header-anchor" href="#撤销和重做修改" aria-label="Permalink to &quot;撤销和重做修改&quot;">​</a></h2><p>点击顶部 <strong>撤销</strong>、<strong>重做</strong>，或使用快捷键。单元格编辑、替换、行操作和机器翻译应用通常会进入历史记录。</p><p>以下操作有特殊边界：</p><ul><li>字幕重新导入会形成新的工作区历史边界。</li><li>使用字幕 <strong>整体替换</strong> 重建匹配分集会清空之前的撤销/重做记录，但未匹配分集仍会保留。</li><li>导出不会改变工作区或历史记录。</li><li>保存后仍可撤销保存前的编辑；是否已保存与能否撤销是两件事。</li></ul><h2 id="重置工作区视图" tabindex="-1">重置工作区视图 <a class="header-anchor" href="#重置工作区视图" aria-label="Permalink to &quot;重置工作区视图&quot;">​</a></h2><p><strong>重置视图</strong>用于清除筛选和临时视图状态，并恢复有效焦点；顶部 <strong>重置布局</strong>用于恢复列宽。它们不会删除字幕内容。</p><h2 id="遇到问题" tabindex="-1">遇到问题 <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题&quot;">​</a></h2><ul><li><strong>点击字幕后表格跳动</strong>：确认是否正在播放或切换视频；暂停时点击已可见行通常不会主动滚动。</li><li><strong>上下键没有切换字幕</strong>：先关闭正在编辑的输入框或对话框，让焦点回到表格/视频区域。</li><li><strong>时间无法应用</strong>：检查格式和结束时间；有警告时先审查重叠或排序变化。</li><li><strong>视频缺失</strong>：字幕仍可编辑；到 <strong>项目设置</strong> 修复视频映射。</li></ul>',43)])])}const b=e(d,[["render",n]]);export{m as __pageData,b as default};
